    pub fn new() -> Self {
        Sha256 { state: H0, buf: [0; 64], buflen: 0, length: 0 }
    }

    pub fn update(&mut self, mut data: &[u8]) {
        self.length = self.length.wrapping_add((data.len() as u64).wrapping_mul(8));
        if self.buflen > 0 {
            let need = 64 - self.buflen;
            if data.len() < need {
                self.buf[self.buflen..self.buflen + data.len()].copy_from_slice(data);
                self.buflen += data.len();
                return;
            }
            self.buf[self.buflen..].copy_from_slice(&data[..need]);
            let block = self.buf;
            Self::compress(&mut self.state, &block);
            self.buflen = 0;
            data = &data[need..];
        }
        while data.len() >= 64 {
            let mut block = [0u8; 64];
            block.copy_from_slice(&data[..64]);
            Self::compress(&mut self.state, &block);
            data = &data[64..];
        }
        if !data.is_empty() {
            self.buf[..data.len()].copy_from_slice(data);
            self.buflen = data.len();
        }
    }

    pub fn finalize(mut self) -> [u8; 32] {
        let length = self.length;
        // Pad
        self.buf[self.buflen] = 0x80;
        self.buflen += 1;
        if self.buflen > 56 {
            for i in self.buflen..64 {
                self.buf[i] = 0;
            }
            let block = self.buf;
            Self::compress(&mut self.state, &block);
            self.buflen = 0;
        }
        for i in self.buflen..56 {
            self.buf[i] = 0;
        }
        self.buf[56..64].copy_from_slice(&length.to_be_bytes());
        let block = self.buf;
        Self::compress(&mut self.state, &block);
        let mut out = [0u8; 32];
        for (i, w) in self.state.iter().enumerate() {
            out[i*4..i*4+4].copy_from_slice(&w.to_be_bytes());
        }
        out
    }

