use std::fs::File;
use std::io::Read;
use std::sync::Mutex;

static RNG_STATE: Mutex<Option<RngState>> = Mutex::new(None);

struct RngState {
    // ChaCha8 state initialized from /dev/urandom
    counter: u64,
    seed: [u8; 32],
}

fn os_random(buf: &mut [u8]) {
    let mut f = File::open("/dev/urandom").expect("open /dev/urandom");
    f.read_exact(buf).expect("read /dev/urandom");
}

pub fn random_bytes(n: usize) -> Vec<u8> {
    let mut v = vec![0u8; n];
    os_random(&mut v);
    v
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Uuid(pub [u8; 16]);

impl Uuid {
    pub fn new_v4() -> Self {
        let mut b = [0u8; 16];
        os_random(&mut b);
        // Set version (4) and variant (RFC 4122)
        b[6] = (b[6] & 0x0f) | 0x40;
        b[8] = (b[8] & 0x3f) | 0x80;
        Uuid(b)
    }

    pub fn nil() -> Self {
        Uuid([0; 16])
    }

    pub fn parse(s: &str) -> Option<Self> {
        let s = s.as_bytes();
        if s.len() != 36 { return None; }
        if s[8] != b'-' || s[13] != b'-' || s[18] != b'-' || s[23] != b'-' {
            return None;
        }
        let mut b = [0u8; 16];
        let mut pos = 0;
        for (i, &c) in s.iter().enumerate() {
            if i == 8 || i == 13 || i == 18 || i == 23 { continue; }
            let d = match c {
                b'0'..=b'9' => c - b'0',
                b'a'..=b'f' => c - b'a' + 10,
                b'A'..=b'F' => c - b'A' + 10,
                _ => return None,
            };
            if pos & 1 == 0 {
                b[pos/2] = d << 4;
            } else {
                b[pos/2] |= d;
            }
            pos += 1;
        }
        Some(Uuid(b))
    }

    pub fn as_bytes(&self) -> &[u8; 16] {
        &self.0
    }

    pub fn to_string(&self) -> String {
        const HEX: &[u8] = b"0123456789abcdef";
        let b = &self.0;
        let mut s = String::with_capacity(36);
        for i in 0..16 {
            if i == 4 || i == 6 || i == 8 || i == 10 {
                s.push('-');
            }
            s.push(HEX[(b[i] >> 4) as usize] as char);
            s.push(HEX[(b[i] & 0xf) as usize] as char);
        }
        s
    }
}

impl std::fmt::Display for Uuid {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.to_string())
    }
}

// Keep for potential future use
fn _unused() { let _ = RNG_STATE.lock(); }
