pub fn parse(s: &str) -> Result<Value, String> {
    let mut p = Parser { s: s.as_bytes(), i: 0 };
    p.skip_ws();
    let v = p.parse_value()?;
    p.skip_ws();
    if p.i != p.s.len() { return Err(format!("trailing data at {}", p.i)); }
    Ok(v)
}

struct Parser<'a> { s: &'a [u8], i: usize }

impl<'a> Parser<'a> {
    fn skip_ws(&mut self) {
        while self.i < self.s.len() {
            let c = self.s[self.i];
            if c == b' ' || c == b'\t' || c == b'\n' || c == b'\r' { self.i += 1; }
            else { break; }
        }
    }

    fn parse_value(&mut self) -> Result<Value, String> {
        self.skip_ws();
        if self.i >= self.s.len() { return Err("unexpected eof".into()); }
        let c = self.s[self.i];
        match c {
            b'"' => Ok(Value::String(self.parse_string()?)),
            b'{' => self.parse_object(),
            b'[' => self.parse_array(),
            b't' | b'f' => self.parse_bool(),
            b'n' => self.parse_null(),
            b'-' | b'0'..=b'9' => self.parse_number(),
            _ => Err(format!("unexpected char {}", c as char)),
        }
    }

    fn parse_string(&mut self) -> Result<String, String> {
        if self.s[self.i] != b'"' { return Err("expected '\"'".into()); }
        self.i += 1;
        let mut out = String::new();
        while self.i < self.s.len() {
            let c = self.s[self.i];
            if c == b'"' { self.i += 1; return Ok(out); }
            if c == b'\\' {
                self.i += 1;
                if self.i >= self.s.len() { return Err("bad escape".into()); }
                let e = self.s[self.i];
                match e {
                    b'"' => out.push('"'),
                    b'\\' => out.push('\\'),
                    b'/' => out.push('/'),
                    b'b' => out.push('\u{08}'),
                    b'f' => out.push('\u{0c}'),
                    b'n' => out.push('\n'),
                    b'r' => out.push('\r'),
                    b't' => out.push('\t'),
                    b'u' => {
                        if self.i + 4 >= self.s.len() { return Err("bad unicode escape".into()); }
                        let hex = std::str::from_utf8(&self.s[self.i+1..self.i+5])
                            .map_err(|_| "bad unicode".to_string())?;
                        let code = u32::from_str_radix(hex, 16).map_err(|_| "bad unicode".to_string())?;
                        self.i += 4;
                        if let Some(c) = char::from_u32(code) { out.push(c); }
                        else { out.push('\u{FFFD}'); }
                    }
                    _ => return Err(format!("bad escape \\{}", e as char)),
                }
                self.i += 1;
            } else {
                out.push(c as char);
                self.i += 1;
            }
        }
        Err("unterminated string".into())
    }

    fn parse_object(&mut self) -> Result<Value, String> {
        self.i += 1;
        let mut kvs = Vec::new();
        self.skip_ws();
        if self.i < self.s.len() && self.s[self.i] == b'}' {
            self.i += 1;
            return Ok(Value::Object(kvs));
        }
        loop {
            self.skip_ws();
            let key = self.parse_string()?;
            self.skip_ws();
            if self.i >= self.s.len() || self.s[self.i] != b':' { return Err("expected ':'".into()); }
            self.i += 1;
            let v = self.parse_value()?;
            kvs.push((key, v));
            self.skip_ws();
            if self.i < self.s.len() && self.s[self.i] == b',' { self.i += 1; continue; }
            if self.i < self.s.len() && self.s[self.i] == b'}' { self.i += 1; return Ok(Value::Object(kvs)); }
            return Err("expected ',' or '}'".into());
        }
    }

    fn parse_array(&mut self) -> Result<Value, String> {
        self.i += 1;
        let mut vals = Vec::new();
        self.skip_ws();
        if self.i < self.s.len() && self.s[self.i] == b']' {
            self.i += 1;
            return Ok(Value::Array(vals));
        }
        loop {
            let v = self.parse_value()?;
            vals.push(v);
            self.skip_ws();
            if self.i < self.s.len() && self.s[self.i] == b',' { self.i += 1; continue; }
            if self.i < self.s.len() && self.s[self.i] == b']' { self.i += 1; return Ok(Value::Array(vals)); }
            return Err("expected ',' or ']'".into());
        }
    }

    fn parse_bool(&mut self) -> Result<Value, String> {
        if self.s[self.i..].starts_with(b"true") { self.i += 4; Ok(Value::Bool(true)) }
        else if self.s[self.i..].starts_with(b"false") { self.i += 5; Ok(Value::Bool(false)) }
        else { Err("expected bool".into()) }
    }
    fn parse_null(&mut self) -> Result<Value, String> {
        if self.s[self.i..].starts_with(b"null") { self.i += 4; Ok(Value::Null) }
        else { Err("expected null".into()) }
    }
    fn parse_number(&mut self) -> Result<Value, String> {
        let start = self.i;
        if self.s[self.i] == b'-' { self.i += 1; }
        while self.i < self.s.len() {
            let c = self.s[self.i];
            if matches!(c, b'0'..=b'9' | b'.' | b'e' | b'E' | b'+' | b'-') {
                self.i += 1;
            } else { break; }
        }
        let s = std::str::from_utf8(&self.s[start..self.i]).map_err(|_| "bad num")?;
        let n: f64 = s.parse().map_err(|_| "bad num")?;
        Ok(Value::Number(n))
    }
}

pub fn encode_string(s: &str, out: &mut String) {
    out.push('"');
    for ch in s.chars() {
        match ch {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            '\u{08}' => out.push_str("\\b"),
            '\u{0c}' => out.push_str("\\f"),
            c if (c as u32) < 0x20 => {
                write!(out, "\\u{:04x}", c as u32).unwrap();
            }
            c => out.push(c),
        }
    }
    out.push('"');
}
