// A framed reader/writer using NUL-terminated JSON messages.
pub struct Framed<T: Read + Write> {
    pub stream: T,
    buf: Vec<u8>,
}

impl<T: Read + Write> Framed<T> {
    pub fn new(stream: T) -> Self {
        Framed { stream, buf: Vec::with_capacity(1024) }
    }

    pub fn send_raw(&mut self, s: &str) -> io::Result<()> {
        self.stream.write_all(s.as_bytes())?;
        self.stream.write_all(&[0u8])?;
        self.stream.flush()
    }

    pub fn send_client(&mut self, m: &ClientMessage) -> io::Result<()> {
        self.send_raw(&m.serialize())
    }

    pub fn send_server(&mut self, m: &ServerMessage) -> io::Result<()> {
        self.send_raw(&m.serialize())
    }

    /// Read next NUL-terminated message. On EOF, returns Ok(None).
    pub fn read_message(&mut self) -> io::Result<Option<String>> {
        loop {
            // Check if buffer has a NUL
            if let Some(pos) = self.buf.iter().position(|&b| b == 0) {
                let msg = self.buf[..pos].to_vec();
                self.buf.drain(..pos + 1);
                let s = String::from_utf8(msg).map_err(|_| io::Error::new(io::ErrorKind::InvalidData, "invalid utf-8"))?;
                return Ok(Some(s));
            }
            let mut tmp = [0u8; 1024];
            let n = self.stream.read(&mut tmp)?;
            if n == 0 { 
                if self.buf.is_empty() { return Ok(None); }
                return Ok(None);
            }
            self.buf.extend_from_slice(&tmp[..n]);
        }
    }
}
