use crate::json::{self, Value};
use crate::uuid::Uuid;
use std::io::{self, Read, Write};

pub const CONTROL_PORT: u16 = 7835;
pub const NETWORK_TIMEOUT: std::time::Duration = std::time::Duration::from_secs(3);
pub const HEARTBEAT_INTERVAL: std::time::Duration = std::time::Duration::from_millis(500);

#[derive(Debug, Clone)]
pub enum ClientMessage {
    Authenticate(String),
    Hello(u16),
    Accept(Uuid),
}

impl ClientMessage {
    pub fn serialize(&self) -> String {
        let mut s = String::new();
        match self {
            ClientMessage::Authenticate(h) => {
                s.push_str("{\"Authenticate\":");
                json::encode_string(h, &mut s);
                s.push('}');
            }
            ClientMessage::Hello(port) => {
                s.push_str("{\"Hello\":");
                s.push_str(&port.to_string());
                s.push('}');
            }
            ClientMessage::Accept(u) => {
                s.push_str("{\"Accept\":");
                json::encode_string(&u.to_string(), &mut s);
                s.push('}');
            }
        }
        s
    }

    pub fn parse(v: &Value) -> Result<Self, String> {
        if let Some(obj) = v.as_object() {
            if obj.len() != 1 { return Err("expected 1 key".into()); }
            let (k, val) = &obj[0];
            return match k.as_str() {
                "Authenticate" => {
                    let s = val.as_str().ok_or("expected string")?;
                    Ok(ClientMessage::Authenticate(s.to_string()))
                }
                "Hello" => {
                    let n = val.as_u64().ok_or("expected number")?;
                    if n > u16::MAX as u64 { return Err("port too large".into()); }
                    Ok(ClientMessage::Hello(n as u16))
                }
                "Accept" => {
                    let s = val.as_str().ok_or("expected string")?;
                    let u = Uuid::parse(s).ok_or("invalid uuid")?;
                    Ok(ClientMessage::Accept(u))
                }
                _ => Err(format!("unknown variant: {}", k)),
            };
        }
        Err("expected object".into())
    }
}

#[derive(Debug, Clone)]
pub enum ServerMessage {
    Challenge(Uuid),
    Hello(u16),
    Heartbeat,
    Connection(Uuid),
    Error(String),
}

impl ServerMessage {
    pub fn serialize(&self) -> String {
        let mut s = String::new();
        match self {
            ServerMessage::Challenge(u) => {
                s.push_str("{\"Challenge\":");
                json::encode_string(&u.to_string(), &mut s);
                s.push('}');
            }
            ServerMessage::Hello(port) => {
                s.push_str("{\"Hello\":");
                s.push_str(&port.to_string());
                s.push('}');
            }
            ServerMessage::Heartbeat => {
                s.push_str("\"Heartbeat\"");
            }
            ServerMessage::Connection(u) => {
                s.push_str("{\"Connection\":");
                json::encode_string(&u.to_string(), &mut s);
                s.push('}');
            }
            ServerMessage::Error(msg) => {
                s.push_str("{\"Error\":");
                json::encode_string(msg, &mut s);
                s.push('}');
            }
        }
        s
    }

    pub fn parse(v: &Value) -> Result<Self, String> {
        if let Value::String(s) = v {
            if s == "Heartbeat" { return Ok(ServerMessage::Heartbeat); }
            return Err(format!("unknown tag: {}", s));
        }
