// Tracing-style logging (stdout, ANSI codes)
use std::io::Write;
use std::sync::{Mutex, OnceLock};
use std::time::{SystemTime, UNIX_EPOCH};

pub struct LogCtx {
    pub spans: Vec<(String, Vec<(String, String)>)>,
}

thread_local! {
    static CTX: std::cell::RefCell<LogCtx> = std::cell::RefCell::new(LogCtx { spans: Vec::new() });
}

pub struct SpanGuard;
impl Drop for SpanGuard {
    fn drop(&mut self) {
        CTX.with(|c| { c.borrow_mut().spans.pop(); });
    }
}

pub fn enter_span(name: &str, fields: Vec<(String, String)>) -> SpanGuard {
    CTX.with(|c| {
        c.borrow_mut().spans.push((name.to_string(), fields));
    });
    SpanGuard
}

fn stdout_lock() -> &'static Mutex<()> {
    static LOCK: OnceLock<Mutex<()>> = OnceLock::new();
    LOCK.get_or_init(|| Mutex::new(()))
}

fn now_iso8601() -> String {
    let d = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
    let secs = d.as_secs() as i64;
    let micros = d.subsec_micros();
    let (y, mo, da, h, mi, se) = epoch_to_ymdhms(secs);
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:06}Z", y, mo, da, h, mi, se, micros)
}

fn is_leap(y: i64) -> bool { (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0) }

fn epoch_to_ymdhms(mut secs: i64) -> (i64, u32, u32, u32, u32, u32) {
    let mut days = secs / 86400;
    secs %= 86400;
    if secs < 0 { secs += 86400; days -= 1; }
    let se = (secs % 60) as u32;
    let mi = ((secs / 60) % 60) as u32;
    let h = (secs / 3600) as u32;

    // days since 1970-01-01
    // Convert to Y-M-D using civil_from_days algorithm (by Howard Hinnant)
    let mut z = days + 719468;
    let era = if z >= 0 { z / 146097 } else { (z - 146096) / 146097 };
    let doe = (z - era * 146097) as i64; // [0, 146096]
    let yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365; // [0, 399]
    let y = yoe + era * 400;
    let doy = doe - (365*yoe + yoe/4 - yoe/100);
    let mp = (5*doy + 2)/153;
    let d = (doy - (153*mp+2)/5 + 1) as u32;
    let m = (if mp < 10 { mp + 3 } else { mp - 9 }) as u32;
    let year = if m <= 2 { y + 1 } else { y };
    let _ = (is_leap, z);
    (year, m, d, h, mi, se)
}

fn render_spans(out: &mut String) {
    CTX.with(|c| {
        for (name, fields) in c.borrow().spans.iter() {
            out.push_str("\x1b[1m");
            out.push_str(name);
            out.push_str("\x1b[0m");
            out.push_str("\x1b[1m{\x1b[0m");
            let mut first = true;
            for (k, v) in fields {
                if !first { out.push(' '); }
                first = false;
                out.push_str("\x1b[3m");
                out.push_str(k);
                out.push_str("\x1b[0m");
                out.push_str("\x1b[2m=\x1b[0m");
                out.push_str(v);
            }
            out.push_str("\x1b[1m}\x1b[0m");
            out.push_str("\x1b[2m:\x1b[0m ");
        }
    });
}

pub fn log_event(level: &str, target: &str, msg: &str, fields: &[(&str, String)]) {
    let ts = now_iso8601();
    let (color, label) = match level {
        "INFO" => ("32", " INFO"),
        "WARN" => ("33", " WARN"),
        "ERROR" => ("31", "ERROR"),
        "DEBUG" => ("34", "DEBUG"),
        "TRACE" => ("35", "TRACE"),
        _ => ("0", level),
    };
    let mut out = String::with_capacity(256);
    out.push_str("\x1b[2m");
    out.push_str(&ts);
    out.push_str("\x1b[0m ");
    out.push_str("\x1b[");
    out.push_str(color);
    out.push_str("m");
    out.push_str(label);
    out.push_str("\x1b[0m ");
    render_spans(&mut out);
    out.push_str("\x1b[2m");
    out.push_str(target);
    out.push_str("\x1b[0m");
    out.push_str("\x1b[2m:\x1b[0m ");
    out.push_str(msg);
    for (k, v) in fields {
        out.push(' ');
        out.push_str("\x1b[3m");
        out.push_str(k);
        out.push_str("\x1b[0m");
        out.push_str("\x1b[2m=\x1b[0m");
        out.push_str(v);
    }
    out.push('\n');
    let _g = stdout_lock().lock();
    let mut so = std::io::stdout().lock();
    let _ = so.write_all(out.as_bytes());
    let _ = so.flush();
}

#[macro_export]
macro_rules! info {
    ($target:expr, $msg:expr) => {
        $crate::log::log_event("INFO", $target, $msg, &[]);
    };
    ($target:expr, $msg:expr, $($k:ident = $v:expr),+ $(,)?) => {
        $crate::log::log_event("INFO", $target, $msg, &[
            $((stringify!($k), format!("{}", $v))),+
        ]);
    };
}

#[macro_export]
macro_rules! warn_log {
    ($target:expr, $msg:expr) => {
        $crate::log::log_event("WARN", $target, $msg, &[]);
    };
    ($target:expr, $msg:expr, $($k:ident = $v:expr),+ $(,)?) => {
        $crate::log::log_event("WARN", $target, $msg, &[
            $((stringify!($k), format!("{}", $v))),+
        ]);
    };
}
