// Tracing-style logging (stdout, ANSI codes)
use std::io::Write;
use std::sync::{Mutex, OnceLock};
use std::time::{SystemTime, UNIX_EPOCH};

pub struct LogCtx {
    pub spans: Vec<(String, Vec<(String, String)>)>,
}

thread_local! {
    static CTX: std::cell::RefCell<LogCtx> = std::cell::RefCell::new(LogCtx { spans: Vec::new() });
}

pub struct SpanGuard;
impl Drop for SpanGuard {
    fn drop(&mut self) {
        CTX.with(|c| { c.borrow_mut().spans.pop(); });
    }
}

pub fn enter_span(name: &str, fields: Vec<(String, String)>) -> SpanGuard {
    CTX.with(|c| {
        c.borrow_mut().spans.push((name.to_string(), fields));
    });
    SpanGuard
}

fn stdout_lock() -> &'static Mutex<()> {
    static LOCK: OnceLock<Mutex<()>> = OnceLock::new();
    LOCK.get_or_init(|| Mutex::new(()))
}

fn now_iso8601() -> String {
    let d = SystemTime::now().duration_since(UNIX_EPOCH).unwrap_or_default();
    let secs = d.as_secs() as i64;
    let micros = d.subsec_micros();
    let (y, mo, da, h, mi, se) = epoch_to_ymdhms(secs);
    format!("{:04}-{:02}-{:02}T{:02}:{:02}:{:02}.{:06}Z", y, mo, da, h, mi, se, micros)
}

fn is_leap(y: i64) -> bool { (y % 4 == 0 && y % 100 != 0) || (y % 400 == 0) }

fn epoch_to_ymdhms(mut secs: i64) -> (i64, u32, u32, u32, u32, u32) {
    let mut days = secs / 86400;
    secs %= 86400;
    if secs < 0 { secs += 86400; days -= 1; }
    let se = (secs % 60) as u32;
    let mi = ((secs / 60) % 60) as u32;
    let h = (secs / 3600) as u32;

    // days since 1970-01-01
    // Convert to Y-M-D using civil_from_days algorithm (by Howard Hinnant)
    let mut z = days + 719468;
    let era = if z >= 0 { z / 146097 } else { (z - 146096) / 146097 };
    let doe = (z - era * 146097) as i64; // [0, 146096]
    let yoe = (doe - doe/1460 + doe/36524 - doe/146096) / 365; // [0, 399]
    let y = yoe + era * 400;
    let doy = doe - (365*yoe + yoe/4 - yoe/100);
    let mp = (5*doy + 2)/153;
    let d = (doy - (153*mp+2)/5 + 1) as u32;
    let m = (if mp < 10 { mp + 3 } else { mp - 9 }) as u32;
    let year = if m <= 2 { y + 1 } else { y };
    let _ = (is_leap, z);
    (year, m, d, h, mi, se)
}

