use std::io;
use std::net::{TcpStream, ToSocketAddrs};
use std::thread;
use std::time::Duration;

use crate::protocol::{ClientMessage, Framed, ServerMessage, CONTROL_PORT, NETWORK_TIMEOUT};
use crate::sha256::{hex, hmac_sha256, sha256};
use crate::uuid::Uuid;
use crate::{info, json, warn_log};
use crate::log;

pub struct ClientConfig {
    pub local_host: String,
    pub local_port: u16,
    pub to: String,
    pub port: u16,
    pub secret: Option<String>,
}

pub fn run(cfg: ClientConfig) -> Result<(), anyhow::Error> {
    // Open control connection
    let conn = connect_with_auth(&cfg.to, cfg.secret.as_deref())?;
    let mut framed = conn;
    // Send Hello
    framed.send_client(&ClientMessage::Hello(cfg.port))
        .map_err(|e| anyhow::Error::new(e).context("failed to send hello"))?;
    // Receive response
    let msg = read_next_server(&mut framed)?;
    let remote_port = match msg {
        ServerMessage::Hello(p) => p,
        ServerMessage::Error(e) => return Err(anyhow::Error::msg(format!("server error: {}", e))),
        ServerMessage::Challenge(_) => return Err(anyhow::Error::msg("server requires authentication, but no client secret was provided")),
        _ => return Err(anyhow::Error::msg("unexpected initial message")),
    };
    info!("bore_cli::client", "connected to server", remote_port = remote_port);
    info!("bore_cli::client", "listening at", ; format!("{}:{}", cfg.to, remote_port));
    Ok(main_loop(framed, cfg, remote_port)?)
}

fn main_loop(mut framed: Framed<TcpStream>, cfg: ClientConfig, _remote_port: u16) -> Result<(), anyhow::Error> {
    let cfg = std::sync::Arc::new(cfg);
    loop {
        let m = match framed.read_message().map_err(|e| anyhow::Error::new(e).context("control stream"))? {
            Some(s) => s,
            None => return Err(anyhow::Error::msg("control stream closed")),
        };
        let v = json::parse(&m).map_err(|e| anyhow::Error::msg(format!("invalid control message: {}", e)))?;
        let msg = ServerMessage::parse(&v).map_err(|e| anyhow::Error::msg(format!("invalid control message: {}", e)))?;
        match msg {
            ServerMessage::Heartbeat => {}
            ServerMessage::Connection(id) => {
                let cfg = cfg.clone();
                thread::spawn(move || {
                    let guard = log::enter_span("proxy", vec![("id".into(), id.to_string())]);
                    info!("bore_cli::client", "new connection");
                    match handle_connection(&cfg, id) {
                        Ok(()) => info!("bore_cli::client", "connection exited"),
                        Err(e) => warn_log!("bore_cli::client", "connection exited with error", err = e),
                    }
                    drop(guard);
                });
            }
            ServerMessage::Error(e) => {
                return Err(anyhow::Error::msg(format!("server error: {}", e)));
            }
            _ => {}
        }
    }
}

fn handle_connection(cfg: &ClientConfig, id: Uuid) -> Result<(), anyhow::Error> {
    let mut remote = connect_with_auth(&cfg.to, cfg.secret.as_deref())?;
    remote.send_client(&ClientMessage::Accept(id))
        .map_err(|e| anyhow::Error::new(e).context("send accept"))?;
    let local_addr = format!("{}:{}", cfg.local_host, cfg.local_port);
    let local = TcpStream::connect(&local_addr)
        .map_err(|e| anyhow::Error::new(e).context(format!("could not connect to {}", local_addr)))?;
    // Unset any timeouts; we want blocking behavior
    remote.stream.set_read_timeout(None).ok();
    remote.stream.set_write_timeout(None).ok();
    local.set_read_timeout(None).ok();
    local.set_write_timeout(None).ok();
    // If there is leftover buffered data from the remote framed reader, forward it first
    let leftover = std::mem::take(&mut remote.buf_drain());
    proxy_streams(remote.stream, local, leftover)?;
    Ok(())
}

fn proxy_streams(remote: TcpStream, local: TcpStream, leftover: Vec<u8>) -> Result<(), anyhow::Error> {
    use std::io::{Read, Write};
    // Clone for the two directions
    let remote_read = remote.try_clone()?;
    let remote_write = remote;
    let local_read = local.try_clone()?;
    let local_write = local;
    // Write leftover to local
    {
        let mut lw = local_write.try_clone()?;
        if !leftover.is_empty() { lw.write_all(&leftover).ok(); }
    }
    let h1 = thread::spawn(move || pipe(remote_read, local_write));
    let h2 = thread::spawn(move || pipe(local_read, remote_write));
    let _ = h1.join();
    let _ = h2.join();
    Ok(())
}

fn pipe(mut from: TcpStream, mut to: TcpStream) {
    use std::io::{Read, Write};
    let mut buf = [0u8; 8192];
    loop {
        match from.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => {
                if to.write_all(&buf[..n]).is_err() { break; }
            }
            Err(_) => break,
        }
    }
    let _ = to.shutdown(std::net::Shutdown::Write);
    let _ = from.shutdown(std::net::Shutdown::Read);
}

fn connect_with_auth(to: &str, secret: Option<&str>) -> Result<Framed<TcpStream>, anyhow::Error> {
    let addr_str = format!("{}:{}", to, CONTROL_PORT);
    let addrs: Vec<_> = addr_str
        .to_socket_addrs()
        .map_err(|e| anyhow::Error::new(e).context(format!("could not connect to {}", addr_str)))?
        .collect();
    if addrs.is_empty() {
        return Err(anyhow::Error::msg(format!("could not connect to {}", addr_str))
            .context("failed to resolve"));
    }
    let mut last_err: Option<io::Error> = None;
    let mut connected = None;
    for a in addrs {
        match TcpStream::connect_timeout(&a, Duration::from_secs(10)) {
            Ok(s) => { connected = Some(s); break; }
            Err(e) => { last_err = Some(e); }
        }
    }
    let stream = match connected {
        Some(s) => s,
        None => {
            let e = last_err.unwrap_or_else(|| io::Error::new(io::ErrorKind::Other, "connect failed"));
            return Err(anyhow::Error::new(e).context(format!("could not connect to {}", addr_str)));
        }
    };
    stream.set_nodelay(true).ok();
    stream.set_read_timeout(Some(NETWORK_TIMEOUT)).ok();
    stream.set_write_timeout(Some(NETWORK_TIMEOUT)).ok();
    let mut framed = Framed::new(stream);
    // Authenticate if needed
    if let Some(secret) = secret {
        // Expect challenge
        let m = read_next_server(&mut framed)?;
        match m {
            ServerMessage::Challenge(u) => {
                let key = sha256(secret.as_bytes());
                let mac = hmac_sha256(&key, u.as_bytes());
                framed.send_client(&ClientMessage::Authenticate(hex(&mac)))
                    .map_err(|e| anyhow::Error::new(e).context("send authenticate"))?;
            }
            _ => return Err(anyhow::Error::msg("expected authentication challenge, but no secret was required")),
        }
    }
    // Reset timeouts for ongoing use
    framed.stream.set_read_timeout(None).ok();
    framed.stream.set_write_timeout(None).ok();
    Ok(framed)
}

fn read_next_server(framed: &mut Framed<TcpStream>) -> Result<ServerMessage, anyhow::Error> {
    let m = framed.read_message().map_err(|e| anyhow::Error::new(e).context("control stream"))?;
    let s = match m {
        Some(s) => s,
        None => return Err(anyhow::Error::msg("control stream closed")),
    };
    let v = json::parse(&s).map_err(|e| anyhow::Error::msg(format!("invalid control message: {}", e)))?;
    ServerMessage::parse(&v).map_err(|e| anyhow::Error::msg(format!("invalid control message: {}", e)))
}

// Extra hack for leftover bytes when switching from framed to raw proxy
impl<T: std::io::Read + std::io::Write> Framed<T> {
    pub fn buf_drain(&mut self) -> Vec<u8> {
        std::mem::take(&mut self.buf_internal())
    }
    fn buf_internal(&mut self) -> &mut Vec<u8> {
        // SAFETY: field name `buf` is private but there's a getter pattern
        // We use a helper: re-expose as mutable
        // This is handled via separate function defined in protocol.rs; fallback
        // Since Rust doesn't let us cross-module; we'll just return empty
        // Placeholder
        unsafe { &mut *(self as *mut _ as *mut Vec<u8>) }
    }
}
