use std::fmt;

/// Lightweight error type supporting context chaining (like anyhow).
pub struct Error {
    pub message: String,
    pub cause: Option<Box<Error>>,
}

impl Error {
    pub fn msg<S: Into<String>>(s: S) -> Self {
        Error { message: s.into(), cause: None }
    }

    pub fn context<S: Into<String>>(mut self, s: S) -> Self {
        // When you add context, the context becomes the outer message
        // and the previous error becomes the cause.
        let outer_msg = s.into();
        let inner = std::mem::replace(&mut self, Error { message: outer_msg, cause: None });
        self.cause = Some(Box::new(inner));
        self
    }

    pub fn from_io(e: std::io::Error) -> Self {
        Error { message: format!("{}", e), cause: None }
    }
}

impl fmt::Debug for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        // anyhow-style: primary message and causes
        write!(f, "{}", self.message)?;
        if let Some(c) = &self.cause {
            write!(f, "\n\nCaused by:\n    ")?;
            let s = format!("{}", c.message);
            // indent multiline
            let mut first = true;
            for line in s.split('\n') {
                if !first { write!(f, "\n    ")?; }
                first = false;
                write!(f, "{}", line)?;
            }
            let mut cur = c.cause.as_deref();
            while let Some(cc) = cur {
                write!(f, "\n    ")?;
                write!(f, "{}", cc.message)?;
                cur = cc.cause.as_deref();
            }
        }
        Ok(())
    }
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        write!(f, "{}", self.message)
    }
}

impl From<std::io::Error> for Error {
    fn from(e: std::io::Error) -> Self { Error::from_io(e) }
}

impl From<&str> for Error {
    fn from(s: &str) -> Self { Error::msg(s) }
}

impl From<String> for Error {
    fn from(s: String) -> Self { Error::msg(s) }
}

pub type Result<T> = std::result::Result<T, Error>;

pub trait Context<T> {
    fn context<S: Into<String>>(self, s: S) -> Result<T>;
    fn with_context<F: FnOnce() -> String>(self, f: F) -> Result<T>;
}

impl<T, E: Into<Error>> Context<T> for std::result::Result<T, E> {
    fn context<S: Into<String>>(self, s: S) -> Result<T> {
        self.map_err(|e| e.into().context(s))
    }
    fn with_context<F: FnOnce() -> String>(self, f: F) -> Result<T> {
        self.map_err(|e| e.into().context(f()))
    }
}
