                s.push_str("{\"Hello\":");
                s.push_str(&port.to_string());
                s.push('}');
            }
            ClientMessage::Accept(u) => {
                s.push_str("{\"Accept\":");
                json::encode_string(&u.to_string(), &mut s);
                s.push('}');
            }
        }
        s
    }

    pub fn parse(v: &Value) -> std::result::Result<Self, String> {
