            let (k, val) = &obj[0];
            return match k.as_str() {
                "Authenticate" => {
                    let s = val.as_str().ok_or("expected string")?;
                    Ok(ClientMessage::Authenticate(s.to_string()))
                }
                "Hello" => {
                    let n = val.as_u64().ok_or("expected number")?;
                    if n > u16::MAX as u64 { return Err("port too large".into()); }
                    Ok(ClientMessage::Hello(n as u16))
                }
                "Accept" => {
                    let s = val.as_str().ok_or("expected string")?;
                    let u = Uuid::parse(s).ok_or("invalid uuid")?;
                    Ok(ClientMessage::Accept(u))
                }
                _ => Err(format!("unknown variant: {}", k)),
            };
        }
        Err("expected object".into())
    }
}

#[derive(Debug, Clone)]
pub enum ServerMessage {
    Challenge(Uuid),
    Hello(u16),
    Heartbeat,
    Connection(Uuid),
    Error(String),
}

impl ServerMessage {
    pub fn serialize(&self) -> String {
        let mut s = String::new();
        match self {
            ServerMessage::Challenge(u) => {
                s.push_str("{\"Challenge\":");
                json::encode_string(&u.to_string(), &mut s);
                s.push('}');
            }
            ServerMessage::Hello(port) => {
                s.push_str("{\"Hello\":");
