                    if n > u16::MAX as u64 { return Err("port too large".into()); }
                    Ok(ServerMessage::Hello(n as u16))
                }
                "Heartbeat" => Ok(ServerMessage::Heartbeat),
                "Connection" => {
                    let s = val.as_str().ok_or("expected string")?;
                    let u = Uuid::parse(s).ok_or("invalid uuid")?;
                    Ok(ServerMessage::Connection(u))
                }
                "Error" => {
                    let s = val.as_str().ok_or("expected string")?;
                    Ok(ServerMessage::Error(s.to_string()))
                }
                _ => Err(format!("unknown variant: {}", k)),
            };
        }
        Err("expected object or string".into())
    }
}

pub struct Framed<T: Read + Write> {
    pub stream: T,
    pub buf: Vec<u8>,
}

impl<T: Read + Write> Framed<T> {
    pub fn new(stream: T) -> Self {
        Framed { stream, buf: Vec::with_capacity(1024) }
    }

    pub fn send_raw(&mut self, s: &str) -> io::Result<()> {
        self.stream.write_all(s.as_bytes())?;
        self.stream.write_all(&[0u8])?;
        self.stream.flush()
    }

