        loop {
            if let Some(pos) = self.buf.iter().position(|&b| b == 0) {
                let msg = self.buf[..pos].to_vec();
                self.buf.drain(..pos + 1);
                let s = String::from_utf8(msg).map_err(|_| io::Error::new(io::ErrorKind::InvalidData, "invalid utf-8"))?;
                return Ok(Some(s));
            }
            let mut tmp = [0u8; 1024];
            let n = self.stream.read(&mut tmp)?;
            if n == 0 {
                return Ok(None);
            }
            self.buf.extend_from_slice(&tmp[..n]);
        }
    }

    pub fn recv_timeout(&mut self, timeout: std::time::Duration) -> Result<Option<ServerMessage>>
    where T: AsTcpStream {
        // Set timeout, read, restore
        let prev = self.stream.as_tcp().read_timeout().ok().flatten();
        self.stream.as_tcp().set_read_timeout(Some(timeout)).ok();
        let res = self.read_message().map_err(|e| Error::from(e));
        self.stream.as_tcp().set_read_timeout(prev).ok();
        let m = res?;
        match m {
            Some(s) => {
                let v = json::parse(&s).map_err(|e| Error::msg(format!("unable to parse message: {}", e)))?;
                let sm = ServerMessage::parse(&v).map_err(|e| Error::msg(format!("unable to parse message: {}", e)))?;
                Ok(Some(sm))
            }
            None => Ok(None),
        }
    }

    pub fn recv_client_timeout(&mut self, timeout: std::time::Duration) -> Result<Option<ClientMessage>>
    where T: AsTcpStream {
        let prev = self.stream.as_tcp().read_timeout().ok().flatten();
        self.stream.as_tcp().set_read_timeout(Some(timeout)).ok();
        let res = self.read_message().map_err(|e| Error::from(e));
        self.stream.as_tcp().set_read_timeout(prev).ok();
        let m = res?;
        match m {
            Some(s) => {
                let v = json::parse(&s).map_err(|e| Error::msg(format!("unable to parse message: {}", e)))?;
                let cm = ClientMessage::parse(&v).map_err(|e| Error::msg(format!("unable to parse message: {}", e)))?;
                Ok(Some(cm))
            }
            None => Ok(None),
        }
    }
}

pub trait AsTcpStream {
    fn as_tcp(&self) -> &std::net::TcpStream;
}

impl AsTcpStream for std::net::TcpStream {
    fn as_tcp(&self) -> &std::net::TcpStream { self }
}
