use crate::errors::{Context, Error, Result};
use crate::protocol::{ClientMessage, Framed, ServerMessage, AsTcpStream, CONTROL_PORT, NETWORK_TIMEOUT};
use crate::sha256::{hex, hmac_sha256, sha256};
use crate::uuid::Uuid;
use crate::{info, log, warn_log};
use std::net::{TcpStream, ToSocketAddrs};
use std::sync::Arc;
use std::thread;
use std::time::Duration;

pub struct ClientConfig {
    pub local_host: String,
    pub local_port: u16,
    pub to: String,
    pub port: u16,
    pub secret: Option<String>,
}

pub fn run(cfg: ClientConfig) -> Result<()> {
    let mut framed = connect_with_auth(&cfg.to, cfg.secret.as_deref())?;
    framed
        .send_client(&ClientMessage::Hello(cfg.port))
        .map_err(Error::from)
        .context("failed to send hello")?;
    let msg = read_next_server(&mut framed)?;
    let remote_port = match msg {
        ServerMessage::Hello(p) => p,
        ServerMessage::Error(e) => return Err(Error::msg(format!("server error: {}", e))),
        ServerMessage::Challenge(_) => {
            return Err(Error::msg(
                "server requires authentication, but no client secret was provided",
            ));
        }
        _ => return Err(Error::msg("unexpected initial message")),
    };
    info!(
        "bore_cli::client",
        "connected to server",
        remote_port = remote_port
    );
    info!(
        "bore_cli::client",
        &format!("listening at {}:{}", cfg.to, remote_port)
    );
    let cfg = Arc::new(cfg);
    main_loop(framed, cfg, remote_port)
}

fn main_loop(mut framed: Framed<TcpStream>, cfg: Arc<ClientConfig>, _remote_port: u16) -> Result<()> {
    loop {
        let m = match framed.read_message().map_err(Error::from)? {
            Some(s) => s,
            None => return Err(Error::msg("control stream closed")),
        };
        let v = crate::json::parse(&m)
            .map_err(|e| Error::msg(format!("invalid control message: {}", e)))?;
        let msg = ServerMessage::parse(&v)
            .map_err(|e| Error::msg(format!("invalid control message: {}", e)))?;
        match msg {
            ServerMessage::Heartbeat => {}
            ServerMessage::Connection(id) => {
                let cfg = cfg.clone();
                thread::spawn(move || {
                    let _guard = log::enter_span("proxy", vec![("id".into(), id.to_string())]);
                    info!("bore_cli::client", "new connection");
                    match handle_connection(&cfg, id) {
                        Ok(()) => info!("bore_cli::client", "connection exited"),
                        Err(e) => {
                            warn_log!(
                                "bore_cli::client",
                                "connection exited with error",
                                err = e.message
                            );
                        }
                    }
                });
            }
            ServerMessage::Error(e) => {
                return Err(Error::msg(format!("server error: {}", e)));
            }
            _ => {}
        }
    }
}

fn handle_connection(cfg: &ClientConfig, id: Uuid) -> Result<()> {
    let mut remote = connect_with_auth(&cfg.to, cfg.secret.as_deref())?;
    remote
        .send_client(&ClientMessage::Accept(id))
        .map_err(Error::from)
        .context("send accept")?;
    let local_addr = format!("{}:{}", cfg.local_host, cfg.local_port);
    let local = TcpStream::connect(&local_addr)
        .map_err(|e| Error::from(e).context(format!("could not connect to {}", local_addr)))?;
    remote.stream.set_read_timeout(None).ok();
    remote.stream.set_write_timeout(None).ok();
    local.set_read_timeout(None).ok();
    local.set_write_timeout(None).ok();
    let leftover = std::mem::take(&mut remote.buf);
    proxy_streams(remote.stream, local, leftover)
}

fn proxy_streams(remote: TcpStream, local: TcpStream, leftover: Vec<u8>) -> Result<()> {
    use std::io::Write;
    let remote_read = remote.try_clone().map_err(Error::from)?;
    let remote_write = remote;
    let local_read = local.try_clone().map_err(Error::from)?;
    let mut local_write = local;
    if !leftover.is_empty() {
        local_write.write_all(&leftover).ok();
    }
    let h1 = thread::spawn(move || pipe(remote_read, local_write));
    let h2 = thread::spawn(move || pipe(local_read, remote_write));
    let _ = h1.join();
    let _ = h2.join();
    Ok(())
}

fn pipe(mut from: TcpStream, mut to: TcpStream) {
    use std::io::{Read, Write};
    let mut buf = [0u8; 8192];
    loop {
        match from.read(&mut buf) {
            Ok(0) => break,
            Ok(n) => {
                if to.write_all(&buf[..n]).is_err() {
                    break;
                }
            }
            Err(_) => break,
        }
    }
    let _ = to.shutdown(std::net::Shutdown::Write);
    let _ = from.shutdown(std::net::Shutdown::Read);
}

fn connect_with_auth(to: &str, secret: Option<&str>) -> Result<Framed<TcpStream>> {
    let addr_str = format!("{}:{}", to, CONTROL_PORT);
    let addrs = addr_str
        .to_socket_addrs()
        .map_err(|e| Error::from(e).context(format!("could not connect to {}", addr_str)))?;
    let mut last_err: Option<std::io::Error> = None;
    let mut connected: Option<TcpStream> = None;
    for a in addrs {
        match TcpStream::connect_timeout(&a, Duration::from_secs(10)) {
            Ok(s) => {
                connected = Some(s);
                break;
            }
            Err(e) => {
                last_err = Some(e);
            }
        }
    }
    let stream = match connected {
        Some(s) => s,
        None => {
            let e = last_err.unwrap_or_else(|| {
                std::io::Error::new(std::io::ErrorKind::Other, "connect failed")
            });
            return Err(Error::from(e).context(format!("could not connect to {}", addr_str)));
        }
    };
    stream.set_nodelay(true).ok();
    let mut framed = Framed::new(stream);
    if let Some(secret) = secret {
        framed.stream.set_read_timeout(Some(NETWORK_TIMEOUT)).ok();
        let m = read_next_server(&mut framed)?;
        framed.stream.set_read_timeout(None).ok();
        match m {
            ServerMessage::Challenge(u) => {
                let key = sha256(secret.as_bytes());
                let mac = hmac_sha256(&key, u.as_bytes());
                framed
                    .send_client(&ClientMessage::Authenticate(hex(&mac)))
                    .map_err(|e| Error::from(e).context("send authenticate"))?;
            }
            _ => {
                return Err(Error::msg(
                    "expected authentication challenge, but no secret was required",
                ));
            }
        }
    }
    Ok(framed)
}

fn read_next_server(framed: &mut Framed<TcpStream>) -> Result<ServerMessage> {
    let m = framed
        .read_message()
        .map_err(|e| Error::from(e).context("control stream"))?;
    let s = match m {
        Some(s) => s,
        None => return Err(Error::msg("control stream closed")),
    };
    let v = crate::json::parse(&s)
        .map_err(|e| Error::msg(format!("invalid control message: {}", e)))?;
    ServerMessage::parse(&v).map_err(|e| Error::msg(format!("invalid control message: {}", e)))
}

// Unused, but ensure AsTcpStream is referenced
#[allow(dead_code)]
fn _a(_: &dyn AsTcpStream) {}
