enum CliErr {
    Anyhow(Error),
    Usage(String, u8),
    Help(String),
}

impl From<Error> for CliErr {
    fn from(e: Error) -> Self { CliErr::Anyhow(e) }
}

fn run(args: &[String]) -> std::result::Result<(), CliErr> {
    let exe_name = "executable";
    let about = "A modern, simple TCP tunnel in Rust that exposes local ports to a remote server, bypassing standard NAT connection firewalls.";
    let mut it = args.iter().skip(1);
    let first = it.next();
    let first = match first {
        Some(s) => s,
        None => {
            return Err(CliErr::Usage(top_help(exe_name, about), 2));
        }
    };
    match first.as_str() {
        "-h" | "--help" => {
            return Err(CliErr::Help(top_help(exe_name, about)));
        }
        "-V" | "--version" => {
            return Err(CliErr::Help(format!("bore-cli {}\n", VERSION)));
        }
        "help" => {
            let sub = it.next();
            match sub.map(|s| s.as_str()) {
                None => return Err(CliErr::Help(top_help(exe_name, about))),
                Some("local") => return Err(CliErr::Help(local_help(exe_name))),
                Some("server") => return Err(CliErr::Help(server_help(exe_name))),
                Some("help") => {
                    // "Print this message or the help of the given subcommand(s)"
                    let s = format!(
                        "Print this message or the help of the given subcommand(s)\n\nUsage: {} help [COMMAND]...\n\nArguments:\n  [COMMAND]...  Print help for the subcommand(s)\n",
                        exe_name
                    );
                    return Err(CliErr::Help(s));
