        -h, --help     Print help\n  \
        -V, --version  Print version\n",
        about, exe
    )
}

fn local_help(exe: &str) -> String {
    format!(
        "Starts a local proxy to the remote server\n\n\
        Usage: {} local [OPTIONS] --to <TO> <LOCAL_PORT>\n\n\
        Arguments:\n  \
        <LOCAL_PORT>  The local port to expose [env: BORE_LOCAL_PORT=]\n\n\
        Options:\n  \
        -l, --local-host <HOST>  The local host to expose [default: localhost]\n  \
        -t, --to <TO>            Address of the remote server to expose local ports to [env: BORE_SERVER=]\n  \
        -p, --port <PORT>        Optional port on the remote server to select [default: 0]\n  \
        -s, --secret <SECRET>    Optional secret for authentication [env: BORE_SECRET]\n  \
        -h, --help               Print help\n",
        exe
    )
}

fn server_help(exe: &str) -> String {
    format!(
        "Runs the remote proxy server\n\n\
        Usage: {} server [OPTIONS]\n\n\
        Options:\n  \
            --min-port <MIN_PORT>          Minimum accepted TCP port number [env: BORE_MIN_PORT=] [default: 1024]\n  \
            --max-port <MAX_PORT>          Maximum accepted TCP port number [env: BORE_MAX_PORT=] [default: 65535]\n  \
        -s, --secret <SECRET>              Optional secret for authentication [env: BORE_SECRET]\n  \
            --bind-addr <BIND_ADDR>        IP address to bind to, clients must reach this [default: 0.0.0.0]\n  \
            --bind-tunnels <BIND_TUNNELS>  IP address where tunnels will listen on, defaults to --bind-addr\n  \
        -h, --help                         Print help\n",
        exe
    )
}

struct Parser<'a> {
    exe: &'a str,
    sub: &'a str,
    args: Vec<String>,
    pos: usize,
    positionals: Vec<String>,
    usage: String,
}

impl<'a> Parser<'a> {
    fn err(&self, msg: String, code: u8) -> CliErr {
        let u = format!(
            "{}\n\nUsage: {} {} {}\n\nFor more information, try '--help'.\n",
            msg, self.exe, self.sub, self.usage
        );
        CliErr::Usage(u, code)
    }

    fn next_value(&mut self, opt: &str) -> std::result::Result<String, CliErr> {
        if self.pos >= self.args.len() {
            return Err(self.err(
                format!("error: a value is required for '{}' but none was supplied", opt),
                2,
            ));
        }
        let v = self.args[self.pos].clone();
        self.pos += 1;
        Ok(v)
    }
}

fn try_split_eq<'a>(s: &'a str, names: &[&str]) -> Option<(&'a str, &'a str)> {
    for name in names {
        if s == *name { return None; }
        if let Some(rest) = s.strip_prefix(&format!("{}=", name)) {
            return Some((name, rest));
        }
    }
    None
}

fn parse_u16(name: &str, s: &str) -> std::result::Result<u16, String> {
    if s.is_empty() {
        return Err(format!(
            "error: invalid value '' for '{}': cannot parse integer from empty string\n\nFor more information, try '--help'.\n",
            name
        ));
    }
    // Check for chars
    let mut nondigit = None;
    for c in s.chars() {
        if !c.is_ascii_digit() { nondigit = Some(c); break; }
    }
    if let Some(_) = nondigit {
        return Err(format!(
            "error: invalid value '{}' for '{}': invalid digit found in string\n\nFor more information, try '--help'.\n",
            s, name
        ));
    }
    // Try parse; if out of range:
    match s.parse::<u64>() {
        Ok(n) if n <= 65535 => Ok(n as u16),
        _ => Err(format!(
            "error: invalid value '{}' for '{}': {} is not in 0..=65535\n\nFor more information, try '--help'.\n",
            s, name, s
        )),
    }
}

fn parse_ip(name: &str, s: &str) -> std::result::Result<IpAddr, String> {
    s.parse::<IpAddr>().map_err(|_| format!(
        "error: invalid value '{}' for '{}': invalid IP address syntax\n\nFor more information, try '--help'.\n",
        s, name
    ))
}

fn env_nonempty(var: &str) -> Option<String> {
    match env::var(var) {
        Ok(v) if !v.is_empty() => Some(v),
        _ => None,
    }
}

fn run_local(exe: &str, args: &[String]) -> std::result::Result<(), CliErr> {
    let mut local_host: Option<String> = None;
    let mut to: Option<String> = None;
    let mut port: Option<String> = None;
    let mut secret: Option<String> = None;
    let mut local_port: Option<String> = None;

    let mut p = Parser {
        exe,
        sub: "local",
        args: args.to_vec(),
        pos: 0,
        positionals: Vec::new(),
        usage: "[OPTIONS] --to <TO> <LOCAL_PORT>".to_string(),
    };

    while p.pos < p.args.len() {
        let a = p.args[p.pos].clone();
        p.pos += 1;
        let eq_opts = ["-l", "--local-host", "-t", "--to", "-p", "--port", "-s", "--secret"];
        // Handle --flag=value syntax
        let mut eq_handled = false;
        for opt in &eq_opts {
            if let Some(v) = a.strip_prefix(&format!("{}=", opt)) {
                match *opt {
                    "-l" | "--local-host" => local_host = Some(v.to_string()),
                    "-t" | "--to" => to = Some(v.to_string()),
                    "-p" | "--port" => port = Some(v.to_string()),
                    "-s" | "--secret" => secret = Some(v.to_string()),
                    _ => unreachable!(),
                }
                eq_handled = true;
                break;
            }
        }
        if eq_handled { continue; }
        match a.as_str() {
            "-l" | "--local-host" => local_host = Some(p.next_value(&a)?),
            "-t" | "--to" => to = Some(p.next_value(&a)?),
            "-p" | "--port" => port = Some(p.next_value(&a)?),
            "-s" | "--secret" => secret = Some(p.next_value(&a)?),
            "-h" | "--help" => {
                return Err(CliErr::Help(local_help(exe)));
            }
            _ => {
                if a.starts_with('-') && a != "-" {
                    // Unexpected flag
                    let msg = format!(
                        "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: {} local [OPTIONS] --to <TO> <LOCAL_PORT>\n\nFor more information, try '--help'.\n",
                        a, a, a, exe
                    );
                    return Err(CliErr::Usage(msg, 2));
                }
                if local_port.is_none() {
                    local_port = Some(a);
                } else {
                    let msg = format!("error: unexpected argument '{}' found\n\nUsage: {} local [OPTIONS] --to <TO> <LOCAL_PORT>\n\nFor more information, try '--help'.\n", a, exe);
                    return Err(CliErr::Usage(msg, 2));
                }
            }
        }
    }

    // Apply env defaults
    if to.is_none() { to = env_nonempty("BORE_SERVER"); }
    if secret.is_none() { secret = env_nonempty("BORE_SECRET"); }
    if local_port.is_none() {
        if let Ok(v) = env::var("BORE_LOCAL_PORT") {
            local_port = Some(v);
        }
    }

    // Required check
    let mut missing: Vec<&str> = Vec::new();
    if to.is_none() { missing.push("--to <TO>"); }
    if local_port.is_none() { missing.push("<LOCAL_PORT>"); }
    if !missing.is_empty() {
        let mut msg = String::from("error: the following required arguments were not provided:\n");
        for m in &missing {
            msg.push_str("  ");
            msg.push_str(m);
            msg.push('\n');
        }
        msg.push_str(&format!("\nUsage: {} local --to <TO> <LOCAL_PORT>\n", exe));
        if args.is_empty() {
            msg.push_str("\nFor more information, try '--help'.\n");
        }
        return Err(CliErr::Usage(msg, 2));
    }

    // Validate local_port: parse u16
    let lp_str = local_port.unwrap();
    let lp = parse_u16("<LOCAL_PORT>", &lp_str).map_err(|m| CliErr::Usage(m, 2))?;
    let p_str = port.unwrap_or_else(|| "0".into());
    let remote_port = parse_u16("--port <PORT>", &p_str).map_err(|m| CliErr::Usage(m, 2))?;

    let cfg = client::ClientConfig {
        local_host: local_host.unwrap_or_else(|| "localhost".to_string()),
        local_port: lp,
        to: to.unwrap(),
        port: remote_port,
        secret,
    };
    client::run(cfg).map_err(CliErr::Anyhow)
}

fn run_server(exe: &str, args: &[String]) -> std::result::Result<(), CliErr> {
    let mut min_port: Option<String> = None;
    let mut max_port: Option<String> = None;
    let mut secret: Option<String> = None;
    let mut bind_addr: Option<String> = None;
    let mut bind_tunnels: Option<String> = None;

    let mut i = 0;
    while i < args.len() {
        let a = args[i].clone();
        i += 1;
        let eq_opts = ["--min-port", "--max-port", "-s", "--secret", "--bind-addr", "--bind-tunnels"];
        let mut eq_handled = false;
        for opt in &eq_opts {
            if let Some(v) = a.strip_prefix(&format!("{}=", opt)) {
                match *opt {
                    "--min-port" => min_port = Some(v.to_string()),
                    "--max-port" => max_port = Some(v.to_string()),
                    "-s" | "--secret" => secret = Some(v.to_string()),
                    "--bind-addr" => bind_addr = Some(v.to_string()),
                    "--bind-tunnels" => bind_tunnels = Some(v.to_string()),
                    _ => unreachable!(),
                }
                eq_handled = true;
                break;
            }
        }
        if eq_handled { continue; }
        match a.as_str() {
            "--min-port" => { if i >= args.len() { return Err(usage_err(exe, "server", "a value is required for '--min-port' but none was supplied")); } min_port = Some(args[i].clone()); i += 1; }
            "--max-port" => { if i >= args.len() { return Err(usage_err(exe, "server", "a value is required for '--max-port' but none was supplied")); } max_port = Some(args[i].clone()); i += 1; }
            "-s" | "--secret" => { if i >= args.len() { return Err(usage_err(exe, "server", "a value is required for '--secret' but none was supplied")); } secret = Some(args[i].clone()); i += 1; }
            "--bind-addr" => { if i >= args.len() { return Err(usage_err(exe, "server", "a value is required for '--bind-addr' but none was supplied")); } bind_addr = Some(args[i].clone()); i += 1; }
            "--bind-tunnels" => { if i >= args.len() { return Err(usage_err(exe, "server", "a value is required for '--bind-tunnels' but none was supplied")); } bind_tunnels = Some(args[i].clone()); i += 1; }
            "-h" | "--help" => return Err(CliErr::Help(server_help(exe))),
            _ => {
                let msg = format!(
                    "error: unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'\n\nUsage: {} server [OPTIONS]\n\nFor more information, try '--help'.\n",
                    a, a, a, exe
                );
                return Err(CliErr::Usage(msg, 2));
            }
        }
    }

    if min_port.is_none() { min_port = env_nonempty("BORE_MIN_PORT"); }
    if max_port.is_none() { max_port = env_nonempty("BORE_MAX_PORT"); }
    if secret.is_none() { secret = env_nonempty("BORE_SECRET"); }

    let min = parse_u16("--min-port <MIN_PORT>", min_port.as_deref().unwrap_or("1024"))
        .map_err(|m| CliErr::Usage(m, 2))?;
    let max = parse_u16("--max-port <MAX_PORT>", max_port.as_deref().unwrap_or("65535"))
        .map_err(|m| CliErr::Usage(m, 2))?;
    let bind_addr = parse_ip(
        "--bind-addr <BIND_ADDR>",
        bind_addr.as_deref().unwrap_or("0.0.0.0"),
    )
    .map_err(|m| CliErr::Usage(m, 2))?;
    let bind_tunnels = match bind_tunnels.as_deref() {
        Some(s) => parse_ip("--bind-tunnels <BIND_TUNNELS>", s).map_err(|m| CliErr::Usage(m, 2))?,
        None => bind_addr,
    };

    if min > max {
        let msg = format!("error: port range is empty\n\nUsage: bore-cli <COMMAND>\n\nFor more information, try '--help'.\n");
        return Err(CliErr::Usage(msg, 2));
    }

    let cfg = server::ServerConfig {
        min_port: min,
        max_port: max,
        secret,
        bind_addr,
        bind_tunnels,
    };
    server::run(cfg).map_err(CliErr::Anyhow)
}

fn usage_err(exe: &str, sub: &str, msg: &str) -> CliErr {
    let usage = match sub {
        "local" => format!("{} local [OPTIONS] --to <TO> <LOCAL_PORT>", exe),
        "server" => format!("{} server [OPTIONS]", exe),
        _ => format!("{} <COMMAND>", exe),
    };
    let m = format!(
        "error: {}\n\nUsage: {}\n\nFor more information, try '--help'.\n",
        msg, usage
    );
    CliErr::Usage(m, 2)
}
