    os_random(&mut v);
    v
}

#[derive(Clone, Copy, Debug, PartialEq, Eq, Hash)]
pub struct Uuid(pub [u8; 16]);

impl Uuid {
    pub fn new_v4() -> Self {
        let mut b = [0u8; 16];
        os_random(&mut b);
        b[6] = (b[6] & 0x0f) | 0x40;
        b[8] = (b[8] & 0x3f) | 0x80;
        Uuid(b)
    }

    #[allow(dead_code)]
    pub fn nil() -> Self { Uuid([0; 16]) }

    pub fn parse(s: &str) -> Option<Self> {
        let s = s.as_bytes();
        if s.len() != 36 { return None; }
        if s[8] != b'-' || s[13] != b'-' || s[18] != b'-' || s[23] != b'-' { return None; }
        let mut b = [0u8; 16];
        let mut pos = 0;
        for (i, &c) in s.iter().enumerate() {
            if i == 8 || i == 13 || i == 18 || i == 23 { continue; }
            let d = match c {
                b'0'..=b'9' => c - b'0',
                b'a'..=b'f' => c - b'a' + 10,
                b'A'..=b'F' => c - b'A' + 10,
                _ => return None,
            };
            if pos & 1 == 0 { b[pos/2] = d << 4; } else { b[pos/2] |= d; }
            pos += 1;
        }
        Some(Uuid(b))
    }

    pub fn as_bytes(&self) -> &[u8; 16] { &self.0 }

    pub fn to_string(&self) -> String {
        const HEX: &[u8] = b"0123456789abcdef";
        let b = &self.0;
        let mut s = String::with_capacity(36);
        for i in 0..16 {
            if i == 4 || i == 6 || i == 8 || i == 10 { s.push('-'); }
            s.push(HEX[(b[i] >> 4) as usize] as char);
            s.push(HEX[(b[i] & 0xf) as usize] as char);
        }
        s
    }
}

impl std::fmt::Display for Uuid {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        f.write_str(&self.to_string())
    }
}
