                out.push_str(v);
            }
            out.push_str("\x1b[1m}\x1b[0m");
            out.push_str("\x1b[2m:\x1b[0m ");
        }
    });
}

pub fn log_event(level: &str, target: &str, msg: &str, fields: &[(&str, String)]) {
    let ts = now_iso8601();
    let (color, label) = match level {
        "INFO" => ("32", " INFO"),
        "WARN" => ("33", " WARN"),
        "ERROR" => ("31", "ERROR"),
        "DEBUG" => ("34", "DEBUG"),
        "TRACE" => ("35", "TRACE"),
        _ => ("0", level),
    };
    let mut out = String::with_capacity(256);
    out.push_str("\x1b[2m");
    out.push_str(&ts);
    out.push_str("\x1b[0m ");
    out.push_str("\x1b[");
    out.push_str(color);
    out.push_str("m");
    out.push_str(label);
    out.push_str("\x1b[0m ");
    render_spans(&mut out);
    out.push_str("\x1b[2m");
    out.push_str(target);
    out.push_str("\x1b[0m");
    out.push_str("\x1b[2m:\x1b[0m ");
    out.push_str(msg);
    for (k, v) in fields {
        out.push(' ');
        out.push_str("\x1b[3m");
        out.push_str(k);
        out.push_str("\x1b[0m");
        out.push_str("\x1b[2m=\x1b[0m");
        out.push_str(v);
    }
    out.push('\n');
    let _g = stdout_lock().lock();
    let mut so = std::io::stdout().lock();
    let _ = so.write_all(out.as_bytes());
    let _ = so.flush();
}

#[macro_export]
macro_rules! info {
    ($target:expr, $msg:expr) => {
        $crate::log::log_event("INFO", $target, $msg, &[])
    };
    ($target:expr, $msg:expr, $($k:ident = $v:expr),+ $(,)?) => {
        $crate::log::log_event("INFO", $target, $msg, &[
            $((stringify!($k), format!("{}", $v))),+
        ])
    };
}

#[macro_export]
macro_rules! warn_log {
    ($target:expr, $msg:expr) => {
        $crate::log::log_event("WARN", $target, $msg, &[])
    };
    ($target:expr, $msg:expr, $($k:ident = $v:expr),+ $(,)?) => {
        $crate::log::log_event("WARN", $target, $msg, &[
            $((stringify!($k), format!("{}", $v))),+
        ])
    };
}
EOF

